<div class="lj-pricing">
  <style>
    .lj-pricing { --lj-primary: #1B2A4A; --lj-ink: #111827; --lj-muted: #6b7280; --lj-border: #e5e7eb; font-family: inherit; color: var(--lj-ink); max-width: 1200px; margin: 0 auto; padding: 24px 16px; }
